(() => {
'use strict';
const SUPPORT='https://t.me/+03WCfVAwaWUzZTkx';
const topics={
 start:{id:'Cara menggunakan BoxCellink dari awal',en:'Getting started with BoxCellink',a:'Selamat datang di BoxCellink!\n\n1. Jelajahi halaman publik untuk mengenal fitur.\n2. Daftar jika ingin fitur akun, histori, atau pembelian yang mensyaratkan login.\n3. Login menggunakan email dan password.\n4. Gunakan navbar untuk membuka Box Video, Media Telegram, Group VIP, Posts, VIP, Akun, Saldo, dan fitur lain.\n5. Baca detail produk, harga, masa akses, dan ketentuan sebelum membeli.\n6. Simpan bukti transaksi dan cek aktivitas akun setelah transaksi.',b:'Welcome to BoxCellink!\n\n1. Explore public pages to learn the available features.\n2. Register if you need account features, history, or purchases requiring sign-in.\n3. Sign in with your email and password.\n4. Use the navbar to access Box Video, Telegram Media, VIP Groups, Posts, VIP, Account, Wallet and other features.\n5. Review product details, price, access period and terms before buying.\n6. Keep transaction records and check account activity after a purchase.',l:[['/index.html','Beranda']]},
 navbar:{id:'Mengenal menu navbar',en:'Understanding the navbar',a:'Navbar adalah navigasi ke fitur website. Box Video untuk katalog video; Media Telegram untuk review media dan instruksi akses; Group VIP untuk grup Telegram; Posts untuk feed komunitas; VIP untuk membership; Akun untuk profil dan aktivitas; Saldo/Afiliasi/Withdraw untuk fitur penghasilan dan pencairan jika tersedia; Chat Bantuan untuk panduan. Menu dapat berbeda sesuai status login dan fitur yang aktif.',b:'The navbar connects you to website features. Box Video is the video catalog; Telegram Media has media reviews and access instructions; VIP Groups lists Telegram groups; Posts is the community feed; VIP is membership; Account shows profile and activity; Wallet/Affiliate/Withdraw are earning and payout tools when available; Help Chat contains guides. Menu items may vary by sign-in state and feature availability.'},
 register:{id:'Cara daftar akun',en:'Register an account',a:'1. Klik Daftar/Register.\n2. Isi semua kolom wajib dengan benar.\n3. Gunakan email aktif untuk pemulihan akun.\n4. Buat password kuat dan unik.\n5. Kirim formulir dan selesaikan verifikasi jika diminta.\n6. Setelah berhasil, buka Login.\nJika error, periksa kolom yang ditandai dan koneksi. Jangan gunakan password yang sama dengan layanan lain.',b:'1. Tap Register/Sign up.\n2. Complete all required fields accurately.\n3. Use an active email for account recovery.\n4. Create a strong, unique password.\n5. Submit and complete verification if requested.\n6. After registration, open Login.\nIf an error appears, check the marked fields and your connection. Avoid reusing passwords.',l:[['/register.html','Daftar']]},
 login:{id:'Cara login / masuk',en:'How to sign in',a:'1. Buka halaman Login.\n2. Masukkan email dan password terdaftar; periksa spasi dan Caps Lock.\n3. Tekan Masuk dan tunggu.\n4. Jika gagal, periksa email, password, koneksi, dan apakah sesi/browser bermasalah.\n5. Jika lupa password, pilih Lupa Kata Sandi.\nJangan berikan password atau kode login kepada siapa pun.',b:'1. Open Login.\n2. Enter your registered email and password; check spaces and Caps Lock.\n3. Tap Sign in and wait.\n4. If it fails, check your email, password, connection and browser/session.\n5. Use Forgot Password if needed.\nNever share your password or login codes.',l:[['/login.html','Login']]},
 forgot:{id:'Cara lupa kata sandi',en:'Forgot password',a:'1. Buka Login dan klik Lupa Kata Sandi.\n2. Masukkan email akun.\n3. Kirim permintaan reset.\n4. Periksa Inbox, Spam/Junk, atau Promotions.\n5. Buka link reset resmi dan buat password baru.\n6. Jika email belum datang, pastikan alamat benar, tunggu beberapa menit, lalu coba lagi. Link reset dapat kedaluwarsa. Jangan bagikan link reset atau OTP.',b:'1. Open Login and tap Forgot Password.\n2. Enter your account email.\n3. Submit the reset request.\n4. Check Inbox, Spam/Junk and Promotions.\n5. Open the official reset link and create a new password.\n6. If no email arrives, verify the address, wait a few minutes and try again. Reset links may expire. Do not share reset links or OTPs.',l:[['/forgot-password.html','Reset password']]},
 profile:{id:'Cara mengubah profil atau foto profil',en:'Edit profile or profile photo',a:'1. Login.\n2. Buka Akun Saya/Profil.\n3. Cari Edit Profil.\n4. Ubah informasi atau pilih foto jika upload tersedia.\n5. Simpan, lalu periksa profil kembali.\nJangan masukkan password, OTP, atau informasi keuangan ke profil publik.',b:'1. Sign in.\n2. Open My Account/Profile.\n3. Find Edit Profile.\n4. Change information or upload a photo if available.\n5. Save and check the profile again.\nDo not place passwords, OTPs or financial details in your public profile.',l:[['/account.html','Akun Saya']]},
 history:{id:'Cara melihat histori tontonan atau pembelian',en:'Find watch history or purchases',a:'1. Login dengan akun yang digunakan saat menonton/membeli.\n2. Buka Akun Saya atau Dashboard.\n3. Cari Histori/History, watch history, atau aktivitas pembelian.\n4. Pilih item untuk melihat kembali.\n5. Jika kosong, periksa apakah kamu menggunakan akun yang benar; aktivitas guest mungkin tidak tersimpan seperti aktivitas member.\nJika pembelian tidak muncul, simpan bukti transaksi dan hubungi bantuan.',b:'1. Sign in with the account used to watch or buy.\n2. Open My Account or Dashboard.\n3. Look for History, watch history or purchase activity.\n4. Select an item to revisit.\n5. If empty, confirm you are using the correct account; guest activity may not be saved like member activity.\nIf a purchase is missing, keep your proof and contact support.',l:[['/account.html','Akun Saya']]},
 search:{id:'Cara mencari video atau media',en:'Search for videos or media',a:'1. Buka Box Video atau Media Telegram sesuai yang dicari.\n2. Ketik judul atau kata kunci pada pencarian jika tersedia.\n3. Gunakan kategori/filter untuk mempersempit pilihan.\n4. Baca detail, harga, dan akses sebelum memilih.\n5. Jika hasil kosong, coba kata yang lebih pendek atau hapus filter.',b:'1. Open Box Video or Telegram Media.\n2. Enter a title or keyword in search if available.\n3. Use categories/filters to narrow results.\n4. Read details, price and access before choosing.\n5. If no results appear, try a shorter keyword or clear filters.'},
 buyMedia:{id:'Cara membeli media Telegram',en:'How to buy Telegram media',a:'1. Buka Media Telegram dan pilih item.\n2. Buka halaman review/detail media.\n3. Periksa judul, deskripsi, harga, dan instruksi akses. Pastikan item benar.\n4. Klik Beli/Checkout yang tersedia.\n5. Ikuti metode pembayaran resmi yang ditampilkan website. Jangan membayar ke rekening/link di luar proses resmi.\n6. Setelah status pembayaran terkonfirmasi, ikuti instruksi akses. Simpan link dan bukti transaksi.\nHarga, metode pembayaran, dan langkah akhir mengikuti halaman checkout saat itu.',b:'1. Open Telegram Media and choose an item.\n2. Open its review/details page.\n3. Check title, description, price and access instructions. Confirm it is the right item.\n4. Tap the available Buy/Checkout button.\n5. Follow the official payment flow on the website. Do not pay through unofficial links or accounts.\n6. After payment is confirmed, follow access instructions and keep your link and receipt.\nPrices, payment methods and final steps follow the checkout page.',l:[['/telegram.html','Media Telegram']]},
 openTelegram:{id:'Cara membuka link media Telegram di Telegram',en:'Open Telegram media links in Telegram',a:'Panduan link media Free maupun berbayar yang membuka bot:\n\n1. Klik link media; pilih buka dengan Telegram jika diminta.\n2. Di chat bot, tekan Start/Mulai.\n3. Bot dapat meminta join grup/channel. Buka link Join yang diberikan dan pastikan kamu sudah bergabung.\n4. Jika bot memakai bahasa China, cari tombol Join/加入 atau tautan grup/channel. Jangan klik link lain yang tidak relevan atau mencurigakan.\n5. Setelah semua grup/channel yang diminta diikuti, kembali ke chat bot.\n6. Tekan tombol verifikasi/konfirmasi (kadang centang hijau ✓) jika ada.\n7. Tunggu bot memeriksa keanggotaan dan mengirim media. Jika belum, cek lagi semua join dan ikuti verifikasi sekali lagi.\nJangan bagikan kode login Telegram atau OTP. Tiap bot mungkin memiliki langkah berbeda.',b:'For free or paid media links that open a Telegram bot:\n\n1. Tap the media link and choose Telegram if prompted.\n2. In the bot chat, tap Start.\n3. The bot may ask you to join groups/channels. Open its Join links and confirm you joined.\n4. If the bot uses Chinese, look for Join/加入 or the group/channel link. Avoid unrelated or suspicious links.\n5. Return to the bot after joining every requested group/channel.\n6. Tap its verification/confirmation button (sometimes a green check ✓) if shown.\n7. Wait for membership verification and media delivery. If it does not arrive, double-check your joins and retry verification once.\nNever share your Telegram login code or OTP. Each bot may have a different flow.',l:[['/telegram.html','Media Telegram']]},
 buyGroups:{id:'Cara membeli Group VIP Telegram',en:'Buy a VIP Telegram Group',a:'1. Buka halaman Group VIP.\n2. Pilih grup dan baca deskripsi, harga, masa akses, serta aturan.\n3. Klik Beli/Checkout.\n4. Selesaikan pembayaran melalui proses resmi.\n5. Setelah berhasil, buka instruksi atau invite yang disediakan.\n6. Jika invite gagal/expired, periksa status transaksi dan hubungi bantuan sebelum membeli ulang.',b:'1. Open VIP Groups.\n2. Select a group and read description, price, access duration and rules.\n3. Tap Buy/Checkout.\n4. Complete payment using the official flow.\n5. After success, open the provided access instructions or invite.\n6. If the invite fails or expires, check the transaction and contact support before buying again.',l:[['/vip-groups.html','Group VIP']]},
 joinGroups:{id:'Cara bergabung ke Group VIP yang sudah dibeli',en:'Join a purchased VIP Group',a:'1. Pastikan transaksi grup sudah berhasil.\n2. Buka link invite/instruksi akses terbaru.\n3. Pilih Telegram dan tekan Join Group/Bergabung.\n4. Pastikan grup muncul di daftar chat Telegram.\n5. Ikuti verifikasi resmi jika diminta.\nJika link expired/invalid, jangan gunakan link lama; simpan bukti pembelian dan hubungi bantuan.',b:'1. Confirm the group purchase succeeded.\n2. Open the latest invite/access instructions.\n3. Choose Telegram and tap Join Group.\n4. Confirm the group appears in Telegram chats.\n5. Complete official verification if requested.\nIf the invite expired or is invalid, keep your purchase proof and contact support rather than using an old invite.',l:[['/vip-groups.html','Group VIP']]},
 buyVip:{id:'Cara membeli akun VIP website',en:'Buy website VIP membership',a:'1. Buka halaman VIP/Upgrade.\n2. Baca benefit, harga, dan durasi paket.\n3. Pilih paket dan klik Upgrade/Beli VIP.\n4. Ikuti checkout dan pembayaran.\n5. Setelah berhasil, periksa status VIP serta masa aktif di Akun Saya.\n6. Jika pembayaran sukses tetapi VIP belum aktif, jangan langsung membeli lagi. Simpan bukti dan laporkan. Benefit, harga, dan masa aktif mengikuti halaman VIP.',b:'1. Open VIP/Upgrade.\n2. Review benefits, price and plan duration.\n3. Choose a plan and tap Upgrade/Buy VIP.\n4. Complete checkout and payment.\n5. Check VIP status and expiration in My Account.\n6. If payment succeeded but VIP is not active, do not buy again immediately. Keep proof and report it. Benefits, price and duration follow the VIP page.',l:[['/vip.html','Paket VIP'],['/account.html','Akun Saya']]},
 freeCheap:{id:'Tips membeli media Telegram dengan harga lebih hemat',en:'Tips for buying Telegram media affordably',a:'1. Bandingkan pilihan dan harga di katalog.\n2. Baca detail supaya tidak salah membeli.\n3. Cek promo atau kode diskon yang sedang aktif.\n4. Jika tersedia, periksa Kode Diskon Saya dan syarat pemakaiannya.\n5. Pastikan harga akhir terlihat sebelum membayar.\nBot tidak dapat memastikan promo aktif atau harga terkini—cek checkout.',b:'1. Compare catalog items and prices.\n2. Read details to avoid purchasing the wrong item.\n3. Check active promotions or discount codes.\n4. Review My Discount Codes and its terms if available.\n5. Confirm the final price before paying.\nThe bot cannot verify live prices or promotions—check checkout.',l:[['/telegram.html','Cari Media'],['/my-discount.html','Kode Diskon']]},
 paidNotReceived:{id:'Sudah membayar tetapi media belum diterima',en:'Paid but media was not delivered',a:'1. Jangan membayar lagi sebelum mengecek transaksi pertama.\n2. Buka Pembayaran/riwayat transaksi dan cari pesanan.\n3. Periksa status: berhasil, pending, atau gagal.\n4. Baca instruksi akses. Untuk Telegram, ikuti Start, Join, dan verifikasi bot.\n5. Jika status sukses tetapi akses belum ada, siapkan ID transaksi, waktu, nama item, dan bukti pembayaran untuk admin.\nJangan kirim password atau OTP.',b:'1. Do not pay again before checking the first order.\n2. Open Payments/transaction history and locate the order.\n3. Check successful, pending or failed status.\n4. Follow access instructions. For Telegram, complete Start, Join and bot verification.\n5. If successful but access is missing, prepare order ID, time, item name and receipt for support.\nNever send passwords or OTPs.',l:[['/payments.html','Pembayaran'],['/telegram.html','Media Telegram']]},
 vipCompare:{id:'Perbedaan Basic, VIP, dan Publisher',en:'Basic, VIP and Publisher differences',a:'Basic adalah akses standar sesuai fitur yang tersedia untuk pengguna biasa. VIP adalah membership berbayar dengan benefit yang tercantum pada halaman paket. Publisher adalah program yang perlu diajukan/disetujui jika diwajibkan, dan dapat menyediakan fitur promosi serta komisi sesuai aturan. Status tidak selalu otomatis berubah setelah pengajuan. Periksa benefit, komisi, dan persyaratan resmi pada halaman program.',b:'Basic is standard access to features available to regular users. VIP is paid membership with benefits listed on its plan page. Publisher is a program that may require application/approval and can provide promotional and commission features according to its rules. Approval does not necessarily happen automatically. Check official benefits and terms.',l:[['/vip.html','Benefit VIP'],['/referral.html','Publisher/Referral']]},
 publisher:{id:'Cara mengajukan Publisher',en:'Apply to become a Publisher',a:'1. Login.\n2. Buka halaman Publisher/Afiliasi/Referral.\n3. Baca syarat program.\n4. Isi form pengajuan secara akurat.\n5. Kirim dan tunggu review admin.\n6. Periksa status di dashboard/notifikasi. Jika disetujui, ikuti petunjuk untuk menggunakan link promosi dan aturan komisi.\nMasukkan data pribadi/payout hanya pada form resmi, bukan chat publik.',b:'1. Sign in.\n2. Open Publisher/Affiliate/Referral.\n3. Review program terms.\n4. Complete the application accurately.\n5. Submit and wait for admin review.\n6. Check status in dashboard/notifications. If approved, follow instructions to use promotional links and commission rules.\nEnter personal or payout information only in official forms.',l:[['/referral.html','Referral/Publisher']]},
 commission:{id:'Cara kerja link referral dan komisi',en:'How referral links and commissions work',a:'1. Pastikan kamu memenuhi syarat Publisher/Afiliasi.\n2. Buka halaman Referral atau dashboard Publisher.\n3. Salin link promosi yang ditetapkan untuk akunmu.\n4. Bagikan kepada audiens yang relevan dengan keterangan jujur.\n5. Transaksi yang memenuhi aturan program dapat dicatat sebagai komisi.\n6. Pantau status komisi di dashboard.\nKlik saja belum tentu menghasilkan komisi. Hindari spam, self-referral yang dilarang, atau traffic manipulatif.',b:'1. Ensure you meet Publisher/Affiliate requirements.\n2. Open Referral or Publisher dashboard.\n3. Copy the promotional link assigned to your account.\n4. Share it with relevant audiences and honest descriptions.\n5. Eligible transactions may earn commission under program rules.\n6. Track commission status in the dashboard.\nClicks alone do not guarantee commission. Avoid spam, prohibited self-referrals or manipulated traffic.',l:[['/referral.html','Referral'],['/publisher-dashboard.html','Publisher Dashboard']]},
 wallet:{id:'Cara melihat saldo dan komisi',en:'Check balance and commissions',a:'1. Login.\n2. Buka Wallet/Saldo/Afiliasi atau dashboard Publisher.\n3. Perhatikan label saldo: pending, tersedia, dibayarkan, atau status lain.\n4. Buka detail mutasi untuk memeriksa sumber komisi.\n5. Jika ada selisih, catat tanggal, nominal, dan ID transaksi lalu laporkan.\nBot tidak dapat membaca saldo akunmu.',b:'1. Sign in.\n2. Open Wallet/Affiliate or Publisher dashboard.\n3. Review labels such as pending, available, paid or other statuses.\n4. Open activity details to check the commission source.\n5. If there is a discrepancy, note date, amount and transaction ID and report it.\nThe bot cannot access your account balance.',l:[['/publisher-dashboard.html','Dashboard Publisher'],['/account.html','Akun']]},
 withdraw:{id:'Cara withdraw / pencairan saldo',en:'Withdraw earnings',a:'1. Pastikan saldo tersedia (bukan pending) memenuhi minimum withdraw di website.\n2. Buka Withdraw.\n3. Pilih/isi metode payout dan data tujuan.\n4. Masukkan nominal, periksa nama penerima, nomor rekening/e-wallet dan nominal.\n5. Submit sekali, lalu pantau status.\n6. Jika pending, ikuti waktu proses yang ditampilkan. Jika ditolak, baca alasan dan koreksi sebelum mencoba lagi.\nJangan kirim PIN, password, OTP, atau kode rahasia.',b:'1. Confirm available (not pending) balance meets the website minimum.\n2. Open Withdraw.\n3. Choose/enter payout method and destination.\n4. Enter amount and double-check recipient, account/e-wallet and amount.\n5. Submit once and track status.\n6. If pending, follow the displayed processing time. If rejected, read the reason and correct it before retrying.\nNever send PINs, passwords or OTPs.',l:[['/withdraw.html','Withdraw'],['/publisher-dashboard.html','Dashboard']]},
 withdrawIssue:{id:'Withdraw tertunda, gagal, atau ditolak',en:'Withdrawal delayed, failed or rejected',a:'1. Buka halaman Withdraw dan baca status serta alasan.\n2. Pastikan saldo tidak pending dan memenuhi minimum.\n3. Periksa data rekening/e-wallet serta nama penerima.\n4. Jangan membuat permintaan berulang untuk transaksi yang sama.\n5. Catat ID permintaan, nominal, tanggal, dan status.\n6. Hubungi bantuan resmi; jangan kirim OTP, password, atau PIN.',b:'1. Open Withdraw and read the status/reason.\n2. Confirm balance is available and meets the minimum.\n3. Check payout destination and recipient name.\n4. Do not submit duplicate requests.\n5. Record request ID, amount, date and status.\n6. Contact official support; never send OTP, password or PIN.',l:[['/withdraw.html','Withdraw'],['/publisher-dashboard.html','Publisher Dashboard']]},
 earn:{id:'Cara mendapatkan penghasilan/“cuan” di web',en:'Earn income on BoxCellink',a:'Program Publisher/Afiliasi adalah salah satu fitur penghasilan jika tersedia dan kamu memenuhi syarat.\n\n1. Baca aturan dan ajukan Publisher jika diperlukan.\n2. Setelah disetujui dan link tersedia, gunakan link referral milikmu.\n3. Bagikan review/post yang memang boleh dipromosikan.\n4. Promosikan secara jujur, tidak menjanjikan penghasilan pasti.\n5. Pantau komisi dan saldo di dashboard.\nPenghasilan tidak dijamin; bergantung pada aktivitas, transaksi eligible, dan kebijakan. Jangan spam atau gunakan traffic palsu.',b:'Publisher/Affiliate may be an earning feature if available and you qualify.\n\n1. Review the rules and apply if required.\n2. Once approved and links are available, use your referral link.\n3. Share reviews/posts you are allowed to promote.\n4. Promote honestly; do not promise guaranteed income.\n5. Monitor commissions and balance in the dashboard.\nEarnings are not guaranteed and depend on activity, eligible transactions and policy. Do not spam or use fake traffic.',l:[['/referral.html','Referral'],['/publisher-dashboard.html','Dashboard']]},
 endorse:{id:'Cara memesan Endorse',en:'Order an Endorse service',a:'1. Buka halaman Endorse.\n2. Baca paket, harga, syarat, dan detail layanan.\n3. Pilih layanan sesuai tujuan promosi.\n4. Isi form campaign/materi secara jelas jika tersedia.\n5. Pastikan detail pesanan, kesepakatan, dan pembayaran tercatat.\n6. Jika belum jelas, hubungi admin melalui kontak yang disediakan di halaman.',b:'1. Open Endorse.\n2. Review packages, pricing, requirements and service details.\n3. Choose a service that fits your campaign.\n4. Complete the campaign/content form clearly if provided.\n5. Confirm order details, agreement and payment record.\n6. Contact support through the page if anything is unclear.'},
 nokos:{id:'Cara membeli akun Telegram/Nokos atau kode OTP',en:'Buy Ready No / Nokos or OTP codes',a:'1. Buka Ready No & Kode OTP.\n2. Pilih produk, negara, atau jenis nomor yang tersedia.\n3. Baca harga, masa penggunaan, keterangan, dan aturan.\n4. Checkout sesuai instruksi website.\n5. Jika kode disediakan melalui panel, gunakan hanya untuk proses sah yang kamu mulai sendiri.\nJangan gunakan nomor/OTP untuk mengambil alih akun orang lain. Jangan bagikan kode login Telegram pribadimu.',b:'1. Open Ready No & OTP Code.\n2. Choose an available product, country or number type.\n3. Review price, usage period, description and terms.\n4. Checkout following website instructions.\n5. If a code is provided in a panel, use it only for a legitimate process you initiated.\nDo not use numbers or OTPs to access someone else’s account. Never share your personal Telegram login code.',l:[['/nokos.html','Ready No & OTP']]},
 posts:{id:'Cara menggunakan Posts / Feed',en:'Use Posts / Feed',a:'1. Buka Posts dari navbar.\n2. Baca postingan komunitas dan keterangan link.\n3. Gunakan Like, Komentar, atau Share jika tersedia.\n4. Untuk membuat posting, pilih Tambah.\n5. Pilih Pastelink atau AutoLink, lalu ikuti form.\n6. Jangan bagikan link berbahaya, data pribadi, OTP, atau konten tanpa izin. Periksa link sebelum dibuka.',b:'1. Open Posts from the navbar.\n2. Read community posts and link descriptions.\n3. Use Like, Comment or Share if available.\n4. Tap Add to create a post.\n5. Choose PasteLink or AutoLink and complete the form.\n6. Do not share unsafe links, private data, OTPs or content without permission. Check links before opening.',l:[['/posts.html','Posts']]},
 postCreate:{id:'Cara membuat postingan',en:'Create a post',a:'1. Login jika diminta.\n2. Buka Posts/Feed lalu tekan Tambah.\n3. Pilih Pastelink atau AutoLink sesuai tujuan.\n4. Isi form, cek caption, dan pastikan link benar.\n5. Publikasikan dan cek apakah postingan muncul.\nJika composer tidak terbuka, refresh halaman, periksa login, lalu coba lagi.',b:'1. Sign in if required.\n2. Open Posts/Feed and tap Add.\n3. Choose PasteLink or AutoLink.\n4. Complete the form and verify caption and link.\n5. Publish and check the post appears.\nIf the composer does not open, refresh, check sign-in and try again.',l:[['/posts.html','Posts'],['/pastelink-create.html','Create PasteLink'],['/autolink.html','Create AutoLink']]},
 pastelink:{id:'Cara membuat Pastelink',en:'Create a PasteLink',a:'1. Login jika diperlukan.\n2. Buka Buat Pastelink.\n3. Isi judul dan isi sesuai batas form.\n4. Tambahkan link/teks; pastikan link benar.\n5. Atur password/expiry hanya jika opsi tersedia dan diperlukan.\n6. Buat/publikasikan.\n7. Salin link, tes dengan membukanya, lalu bagikan.\nJangan masukkan password pribadi, OTP, atau data sensitif.',b:'1. Sign in if required.\n2. Open Create PasteLink.\n3. Enter title and content within the displayed limits.\n4. Add your link/text and verify it.\n5. Set password/expiry only if available and needed.\n6. Create/publish.\n7. Copy, test the link and share it.\nDo not include personal passwords, OTPs or sensitive data.',l:[['/pastelink-create.html','Buat PasteLink']]},
 pasteTrouble:{id:'Pastelink gagal dibuat, dibuka, atau link error',en:'PasteLink troubleshooting',a:'1. Pastikan login jika fitur mensyaratkannya.\n2. Periksa link tujuan dan pastikan dapat diakses.\n3. Lengkapi kolom wajib dan ikuti batas karakter.\n4. Jika link dilindungi password, gunakan password Pastelink yang benar.\n5. Periksa masa berlaku.\n6. Jika masih gagal, catat pesan error dan URL (jangan sertakan password) untuk laporan.',b:'1. Sign in if required.\n2. Verify the destination link opens.\n3. Complete required fields and character limits.\n4. If protected, use the correct PasteLink password.\n5. Check expiration.\n6. If it still fails, record the error and URL (not its password) for support.',l:[['/pastelink-create.html','PasteLink']]},
 autolink:{id:'Cara membuat AutoLink',en:'Create an AutoLink',a:'1. Login jika diminta.\n2. Buka AutoLink atau pilih Buat AutoLink dari Posts.\n3. Masukkan URL tujuan yang valid.\n4. Lengkapi pengaturan yang ditampilkan; periksa task, redirect, monetisasi, atau opsi iklan jika tersedia.\n5. Simpan/buat link.\n6. Salin dan tes link di tab baru.\n7. Bagikan secara wajar, jangan spam.\nPengaturan dapat berubah; ikuti instruksi AutoLink Studio yang tampil.',b:'1. Sign in if required.\n2. Open AutoLink or choose Create AutoLink from Posts.\n3. Enter a valid destination URL.\n4. Review displayed settings, including tasks, redirect, monetization or ad options if available.\n5. Save/create the link.\n6. Copy and test it in a new tab.\n7. Share responsibly. Settings can change; follow current AutoLink Studio instructions.',l:[['/autolink.html','AutoLink']]},
 autolinkError:{id:'AutoLink tidak mengarah ke halaman yang benar',en:'AutoLink redirects incorrectly',a:'1. Gunakan link AutoLink terbaru.\n2. Tes di tab baru atau mode privat.\n3. Periksa URL tujuan dan urutan task di editor jika tersedia.\n4. Pastikan pengaturan disimpan dan tidak ada task yang belum selesai.\n5. Jika tetap salah, laporkan link, tujuan yang diharapkan, dan screenshot error.\nSimpan konfigurasi sebelum mengubah task secara acak.',b:'1. Test the latest AutoLink in a new/private tab.\n2. Check destination URL and task order in the editor if available.\n3. Ensure settings are saved and tasks are complete.\n4. If still incorrect, report the link, expected destination and an error screenshot.\nSave your configuration before making random changes.',l:[['/autolink.html','AutoLink']]},
 wallet:{id:'Cara melihat saldo dan komisi',en:'Check balance and commissions',a:'1. Login.\n2. Buka Saldo/Wallet/Afiliasi atau Dashboard Publisher.\n3. Perhatikan status pending, tersedia, dibayarkan, atau label lain.\n4. Buka mutasi/detail komisi.\n5. Jika ada selisih, catat tanggal, jumlah, dan ID transaksi lalu laporkan.\nBot tidak dapat melihat saldo privat.',b:'1. Sign in.\n2. Open Wallet/Affiliate or Publisher dashboard.\n3. Review pending, available, paid or other status labels.\n4. Open commission details.\n5. For discrepancies, note date, amount and transaction ID and report it.\nThe bot cannot access private balances.',l:[['/publisher-dashboard.html','Publisher Dashboard'],['/account.html','Akun']]},
 publisher:{id:'Cara mengajukan Publisher',en:'Apply to become a Publisher',a:'1. Login.\n2. Buka Publisher/Afiliasi/Referral.\n3. Baca syarat program.\n4. Isi form pengajuan dengan data akurat.\n5. Kirim dan tunggu pemeriksaan admin.\n6. Cek status dashboard/notifikasi. Jika disetujui, ikuti panduan link promosi dan komisi.\nMasukkan data pribadi hanya di form resmi.',b:'1. Sign in.\n2. Open Publisher/Affiliate/Referral.\n3. Read program requirements.\n4. Complete the application accurately.\n5. Submit and wait for admin review.\n6. Check dashboard/notifications. If approved, follow promotional link and commission instructions.\nEnter personal data only in official forms.',l:[['/referral.html','Publisher/Referral']]},
 commission:{id:'Cara kerja link referral dan komisi',en:'How referral links and commissions work',a:'1. Pastikan memenuhi syarat Publisher/Afiliasi.\n2. Buka Referral atau Dashboard Publisher.\n3. Salin link promosi khusus akunmu.\n4. Bagikan dengan audiens relevan dan keterangan jujur.\n5. Transaksi eligible dapat menghasilkan komisi sesuai aturan.\n6. Pantau komisi di dashboard. Klik tidak otomatis menghasilkan komisi. Hindari spam atau traffic manipulatif.',b:'1. Meet Publisher/Affiliate requirements.\n2. Open Referral or Publisher Dashboard.\n3. Copy your assigned promotion link.\n4. Share it with a relevant audience honestly.\n5. Eligible transactions may earn commission under program rules.\n6. Track it in the dashboard. Clicks alone do not guarantee earnings. Avoid spam or manipulated traffic.',l:[['/referral.html','Referral'],['/publisher-dashboard.html','Dashboard']]},
 withdraw:{id:'Cara withdraw / pencairan saldo',en:'Withdraw earnings',a:'1. Pastikan saldo tersedia (bukan pending) dan memenuhi minimum withdraw.\n2. Buka Withdraw.\n3. Pilih/isi metode payout dan data tujuan.\n4. Masukkan nominal, periksa nama penerima dan nomor rekening/e-wallet.\n5. Submit sekali, lalu pantau status.\n6. Pending: ikuti waktu proses yang ditampilkan. Ditolak: baca alasan, perbaiki data/ketentuan sebelum mencoba lagi.\nJangan kirim PIN, password, atau OTP.',b:'1. Ensure available (not pending) balance meets minimum.\n2. Open Withdraw.\n3. Select/enter payout method and destination.\n4. Enter amount and verify recipient and account/e-wallet details.\n5. Submit once and track status.\n6. Pending: follow displayed processing time. Rejected: read reason and correct details before retrying.\nNever share PINs, passwords or OTPs.',l:[['/withdraw.html','Withdraw'],['/publisher-dashboard.html','Dashboard']]},
 withdrawIssue:{id:'Withdraw tertunda, gagal, atau ditolak',en:'Withdrawal delayed, failed or rejected',a:'1. Buka Withdraw dan baca status/alasan.\n2. Pastikan saldo tersedia dan memenuhi minimum.\n3. Periksa rekening/e-wallet dan nama penerima.\n4. Hindari permintaan berulang.\n5. Catat ID permintaan, nominal, tanggal, dan status.\n6. Hubungi bantuan resmi; jangan kirim password, PIN, atau OTP.',b:'1. Open Withdraw and read status/reason.\n2. Ensure balance is available and meets minimum.\n3. Verify payout details and recipient name.\n4. Avoid duplicate requests.\n5. Record request ID, amount, date and status.\n6. Contact official support; never share password, PIN or OTP.',l:[['/withdraw.html','Withdraw']]},
 endorse:{id:'Cara memesan Endorse',en:'Order an Endorse service',a:'1. Buka halaman Endorse.\n2. Baca paket, harga, syarat dan detail layanan.\n3. Pilih layanan yang sesuai.\n4. Isi detail campaign/materi pada form jika tersedia.\n5. Periksa kesepakatan, pesanan, dan pembayaran.\n6. Jika belum jelas, tanyakan admin melalui kontak halaman.',b:'1. Open Endorse.\n2. Review packages, prices, terms and details.\n3. Choose a suitable service.\n4. Fill campaign/content details if the form is available.\n5. Review order, agreement and payment.\n6. Ask support if anything is unclear.'},
 nokos:{id:'Cara membeli akun Telegram/Nokos atau kode OTP',en:'Buy Ready No / Nokos or OTP codes',a:'1. Buka Ready No & Kode OTP.\n2. Pilih produk/negara/jenis nomor yang tersedia.\n3. Baca harga, keterangan, masa pakai dan aturan.\n4. Checkout sesuai instruksi website.\n5. Jika kode muncul di panel, gunakan hanya untuk proses sah yang kamu mulai sendiri.\nJangan gunakan nomor/OTP untuk mengambil alih akun orang lain. Jangan bagikan kode login Telegram pribadimu.',b:'1. Open Ready No & OTP Code.\n2. Choose an available product/country/number type.\n3. Review price, details, usage period and rules.\n4. Checkout using website instructions.\n5. Use codes only for a legitimate process you initiated.\nDo not use numbers or OTPs to take over someone else’s account. Never share your personal Telegram login code.',l:[['/nokos.html','Ready No & OTP']]},
 paymentPending:{id:'Pembayaran masih pending',en:'Payment is pending',a:'1. Buka Pembayaran dan cek status order.\n2. Pastikan langkah pembayaran sudah selesai; jangan membayar lagi sebelum status transaksi pertama jelas.\n3. Tunggu konfirmasi sesuai metode yang ditampilkan.\n4. Jika status tidak berubah, siapkan ID order, waktu, nominal, dan bukti transaksi.\n5. Hubungi bantuan resmi. Jangan kirim OTP atau data sensitif.',b:'1. Open Payments and check the order status.\n2. Confirm payment steps are complete; do not pay again while the first order is unresolved.\n3. Wait for confirmation according to the displayed method.\n4. If unchanged, prepare order ID, time, amount and receipt.\n5. Contact official support. Do not share OTPs or sensitive details.',l:[['/payments.html','Pembayaran']]},
 paymentFailed:{id:'Pembayaran gagal atau tidak tercatat',en:'Payment failed or missing',a:'1. Baca pesan error.\n2. Periksa metode pembayaran, saldo, dan koneksi.\n3. Jika dana terpotong tetapi order gagal, jangan langsung mengulang pembayaran.\n4. Catat ID order, nominal, waktu, dan bukti transaksi.\n5. Hubungi bantuan resmi untuk pemeriksaan.',b:'1. Read the error message.\n2. Check payment method, funds and connection.\n3. If funds were deducted but the order failed, do not immediately retry.\n4. Record order ID, amount, time and proof.\n5. Contact official support.',l:[['/payments.html','Pembayaran']]},
 linkError:{id:'Link media/review rusak atau kedaluwarsa',en:'Media/review link is broken or expired',a:'1. Pastikan link tersalin lengkap.\n2. Coba browser atau aplikasi yang sesuai (Telegram untuk link Telegram).\n3. Periksa masa berlaku atau batas akses.\n4. Jika media yang sudah dibeli tidak bisa dibuka, jangan membeli ulang dulu.\n5. Laporkan nama item, ID transaksi, link bermasalah, dan pesan error tanpa informasi rahasia.',b:'1. Confirm the link was copied completely.\n2. Try the intended browser/app (Telegram for Telegram links).\n3. Check expiry or access restrictions.\n4. If a purchased item is inaccessible, do not buy it again yet.\n5. Report item name, transaction ID, link and error message without sensitive data.',l:[['/telegram.html','Media Telegram']]},
 browser:{id:'Website lambat, tidak tampil, atau tombol tidak merespons',en:'Website slow, broken or buttons unresponsive',a:'1. Pastikan internet stabil.\n2. Refresh sekali.\n3. Tutup dan buka ulang browser.\n4. Coba browser terbaru atau tab privat untuk memeriksa cache/session.\n5. Login kembali jika sesi habis.\n6. Jika berulang, catat halaman, tombol, waktu, browser, dan pesan error.\nJangan tekan submit/pembayaran berkali-kali saat proses berjalan.',b:'1. Check your connection.\n2. Refresh once.\n3. Restart your browser.\n4. Try an updated browser or private tab to check cache/session.\n5. Sign in again if your session expired.\n6. If it persists, record page, button, time, browser and error.\nDo not submit/payment-click repeatedly while processing.'},
 safeLinks:{id:'Cara memeriksa keamanan link',en:'Check link safety',a:'• Buka link hanya dari sumber tepercaya.\n• Periksa domain sebelum login atau mengisi data.\n• Jangan masukkan password, OTP, PIN, atau data kartu pada form tidak dikenal.\n• Periksa nama bot Telegram dan instruksinya.\n• Jangan instal APK/file tidak dikenal hanya karena link meminta.\nJika link mencurigakan, hentikan dan laporkan.',b:'• Open links only from sources you trust.\n• Check the domain before signing in or entering data.\n• Never enter passwords, OTPs, PINs or card details on unknown forms.\n• Check Telegram bot names and prompts.\n• Do not install unknown APKs/files just because a link asks.\nStop and report suspicious links.'},
 contact:{id:'Cara menghubungi admin jika bot belum membantu',en:'Contact admin if the bot cannot help',a:'Agar admin lebih cepat memeriksa, siapkan:\n• Halaman/fitur yang digunakan.\n• Ringkasan masalah dan langkah yang sudah dicoba.\n• ID transaksi/order untuk masalah pembayaran atau akses.\n• Screenshot error dengan data pribadi disamarkan.\nJangan kirim password, OTP, PIN, kode login, atau data kartu lengkap. Gunakan kanal bantuan resmi.',b:'To help support investigate faster, prepare:\n• Page/feature you used.\n• Short description and steps already tried.\n• Order/transaction ID for payment/access issues.\n• Screenshot with private information hidden.\nNever send passwords, OTPs, PINs, login codes or full card details. Use official support channels.',l:[['SUPPORT','Telegram Support']]},
 unknown:{id:'Saya masih bingung / pertanyaan tidak ditemukan',en:'Still confused / topic not found',a:'Tidak apa-apa! Coba ketik kata kunci singkat seperti “saldo”, “OTP”, “login”, atau “link error”. Kamu juga bisa pilih topik di bawah.\n\nBot ini memakai panduan yang disimpan, bukan AI live, dan tidak bisa membaca data akun, order, saldo, atau status pembayaran. Jika belum menemukan jawaban, hubungi bantuan resmi.',b:'No problem! Try a short keyword such as “balance”, “OTP”, “login” or “broken link”. You can also choose a guide below.\n\nThis bot uses a built-in guide library, not live AI. It cannot read your account, order, balance or payment status. Contact official support if you still need help.',l:[['SUPPORT','Support']]}
};
const groups=[{id:'Getting started',en:'Getting started',keys:['start','navbar','register','login','forgot','profile','history','search']},{id:'Media Telegram: purchase & access',en:'Telegram media: purchase & access',keys:['buyMedia','openTelegram','buyGroups','joinGroups','buyVip','freeCheap','paidNotReceived']},{id:'VIP, Publisher, wallet & withdrawals',en:'VIP, Publisher, wallet & withdrawals',keys:['vipCompare','publisher','commission','wallet','withdraw','withdrawIssue','earn']},{id:'Posts, PasteLink & AutoLink',en:'Posts, PasteLink & AutoLink',keys:['posts','postCreate','pastelink','pasteTrouble','autolink','autolinkError']},{id:'VIP Group, OTP & Endorse',en:'VIP Groups, OTP & Endorse',keys:['nokos','endorse','vipGroupTrouble','accountPurchase']},{id:'Security & troubleshooting',en:'Security & troubleshooting',keys:['safeLinks','paymentPending','paymentFailed','linkError','browser','contact','unknown']}];
topics.autolinkError={id:'AutoLink tidak mengarah ke halaman yang benar',en:'AutoLink redirects incorrectly',a:'1. Gunakan link AutoLink terbaru.\n2. Tes di tab baru atau mode privat.\n3. Periksa URL tujuan dan urutan task di editor jika tersedia.\n4. Pastikan pengaturan sudah disimpan dan tidak ada task yang belum selesai.\n5. Jika masih salah, laporkan link, tujuan yang diharapkan, dan screenshot error.\nSimpan konfigurasi sebelum mengubah task secara acak.',b:'1. Test the latest AutoLink in a new or private tab.\n2. Check the destination URL and task order in the editor if available.\n3. Ensure settings are saved and all tasks are complete.\n4. If still incorrect, report the link, expected destination and an error screenshot.\nSave your configuration before making random changes.',l:[['/autolink.html','AutoLink']]};
topics.vipGroupTrouble={id:'Link Group VIP tidak bisa digunakan',en:'VIP Group invite does not work',a:'1. Periksa transaksi dan pastikan pembelian grup berstatus berhasil.\n2. Buka instruksi akses dan gunakan invite terbaru, bukan link lama.\n3. Pastikan Telegram yang terbuka adalah akun yang ingin digunakan.\n4. Jika link expired, invalid, atau grup tidak dapat diakses, jangan membeli ulang.\n5. Siapkan ID transaksi, nama grup, dan pesan error/screenshot (sembunyikan data pribadi).\n6. Hubungi bantuan resmi untuk pengecekan atau invite baru jika memenuhi syarat.',b:'1. Check the transaction and confirm the group purchase succeeded.\n2. Use the latest invite in the access instructions, not an old link.\n3. Confirm Telegram is open with the account you intend to use.\n4. If the link expired, is invalid or the group is inaccessible, do not buy again.\n5. Prepare transaction ID, group name and error/screenshot (hide private information).\n6. Contact official support for review or a new invite if eligible.',l:[['/vip-groups.html','Group VIP']]};
topics.accountPurchase={id:'Cara menemukan pembelian atau transaksi',en:'Find purchases and transactions',a:'1. Login dengan akun yang dipakai saat transaksi.\n2. Buka Akun, Dashboard, atau Pembayaran.\n3. Cari daftar transaksi/riwayat dan pilih item yang dicari.\n4. Periksa tanggal, nominal, status, dan instruksi akses.\n5. Jika tidak muncul, cek apakah pembelian dilakukan menggunakan akun/email berbeda.\n6. Untuk laporan, siapkan ID order dan bukti yang relevan; jangan kirim OTP atau password.',b:'1. Sign in with the account used at purchase.\n2. Open Account, Dashboard or Payments.\n3. Find transaction history and select the item.\n4. Check date, amount, status and access instructions.\n5. If missing, verify whether another account/email was used.\n6. For support, prepare order ID and relevant receipt; never share OTPs or passwords.',l:[['/account.html','My Account'],['/payments.html','Payments']]};
// Aliases point to existing detailed help entries.
topics.navbar=topics.navbar||topics.nav; topics.safeLinks=topics.safeLinks; topics.freeCheap=topics.freeCheap||topics.cheapMedia;
// Remove catalog aliases with missing entries and map English labels cleanly.
const keys=groups.flatMap(g=>g.keys).filter(k=>topics[k]);
const titleEN={start:'Getting started with BoxCellink',navbar:'Understanding the navbar',register:'Register an account',login:'How to sign in',forgot:'Forgot password',profile:'Edit profile or profile photo',history:'Find watch history or purchases',search:'Search videos or media',buyMedia:'How to buy Telegram media',openTelegram:'Open Telegram media links in Telegram',buyGroups:'Buy a VIP Telegram Group',joinGroups:'Join a purchased VIP Group',buyVip:'Buy website VIP membership',freeCheap:'Tips for buying Telegram media affordably',paidNotReceived:'Paid but media was not delivered',vipCompare:'Basic, VIP and Publisher differences',publisher:'Apply to become a Publisher',commission:'How referral links and commissions work',wallet:'Check balance and commissions',withdraw:'Withdraw earnings',withdrawIssue:'Withdrawal delayed, failed or rejected',earn:'Earn income on BoxCellink',posts:'Use Posts / Feed',postCreate:'Create a post',pastelink:'Create a PasteLink',pasteTrouble:'PasteLink troubleshooting',autolink:'Create an AutoLink',autolinkError:'AutoLink redirects incorrectly',endorse:'Order an Endorse service',nokos:'Buy Ready No / Nokos or OTP codes',paymentPending:'Payment is pending',paymentFailed:'Payment failed or missing',linkError:'Media/review link is broken or expired',browser:'Website slow, broken or buttons unresponsive',safeLinks:'Check link safety',contact:'Contact support if the bot cannot help',unknown:'Still confused / topic not found'};
const linkEN={'Beranda':'Home','Daftar':'Register','Login':'Login','Reset password':'Reset password','Akun Saya':'My Account','Media Telegram':'Telegram Media','Group VIP':'VIP Groups','Paket VIP':'VIP Plans','Referral':'Referral','Publisher Dashboard':'Publisher Dashboard','Withdraw':'Withdraw','Posts':'Posts','Buat PasteLink':'Create PasteLink','Buat AutoLink':'Create AutoLink','Kode Diskon':'Discount Codes','Pembayaran':'Payments','Dashboard Publisher':'Publisher Dashboard','Cari Media':'Browse media','Akun':'Account','Referral/Publisher':'Referral/Publisher','Support':'Support','Telegram Support':'Telegram Support'};
const translations={id:{title:'Chat Bantuan BoxCellink',sub:'Panduan lengkap penggunaan website. Tekan Start untuk memulai.',welcome:'Halo! Saya Bot Bantuan BoxCellink. Klik Start untuk memilih topik, mencari panduan, atau mengetik pertanyaan.',start:'Start',status:'Siap membantu • Ready to help',hint:'Chat ini menggunakan panduan tersimpan. Jika belum menemukan jawaban, pilih Hubungi Bantuan.',disclaimer:'Bot ini menggunakan panduan tersimpan, bukan AI live. Harga, promo, status transaksi, dan persyaratan terbaru mengikuti informasi pada website.',search:'Ketik pertanyaan atau cari panduan…',yes:'Ya, membantu',no:'Belum membantu',contact:'Hubungi Bantuan',restart:'Mulai ulang',thanks:'Terima kasih! Senang panduan ini membantu.',sorry:'Maaf belum membantu. Pilih topik terkait, coba pertanyaan lebih spesifik, atau hubungi admin.',notfound:'Saya belum menemukan panduan yang cocok. Coba kata kunci lain atau pilih topik di bawah.',empty:'Tidak ada panduan cocok. Coba kata lain.',startPrompt:'Silakan pilih kategori, topik, atau ketik pertanyaanmu.'},en:{title:'BoxCellink Help Chat',sub:'Step-by-step website guides. Press Start to begin.',welcome:'Hello! I am the BoxCellink Help Bot. Press Start to browse topics, search guides or type a question.',start:'Start',status:'Ready to help',hint:'This chat uses a built-in guide library. Contact support if you cannot find an answer.',disclaimer:'This bot uses a guide library, not live AI. Current prices, promotions, transaction status and requirements follow the website.',search:'Type a question or search for a guide…',yes:'Yes, helpful',no:'Not yet',contact:'Contact support',restart:'Restart chat',thanks:'Thanks! Glad this guide helped.',sorry:'Sorry it did not help. Choose a related topic, ask more specifically or contact support.',notfound:'I could not find a matching guide. Try another keyword or choose a topic below.',empty:'No matching guide. Try another keyword.',startPrompt:'Choose a category, topic, or type your question.'}};
let lang=(localStorage.getItem('boxcellink_lang')||'id')==='en'?'en':'id',started=false,typing=false;
const $=id=>document.getElementById(id),msg=$('helpMessages'),acts=$('helpActions'),inputArea=$('helpInputArea'),input=$('helpQuestion');
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function title(k){return lang==='en'?(titleEN[k]||topics[k]?.en||k):(topics[k]?.id||k);}
function text(k){return topics[k]?.[lang==='en'?'b':'a']||translations[lang].notfound;}
function localize(){const t=translations[lang];document.documentElement.lang=lang;document.querySelector('[data-help-title]').textContent=t.title;document.querySelector('[data-help-sub]').textContent=t.sub;if(!started)document.querySelector('[data-help-welcome]').textContent=t.welcome;document.querySelector('[data-help-status]').textContent=t.status;document.querySelector('[data-help-disclaimer]').textContent=t.disclaimer;document.querySelector('[data-help-input-hint]').textContent=t.hint;document.querySelector('[data-help-start]').textContent=t.start;$('helpLang').querySelector('span').textContent=lang.toUpperCase();input.placeholder=t.search;}
function scroll(){msg.scrollTop=msg.scrollHeight;}
function addMessage(txt,who='bot'){const wrap=document.createElement('div');wrap.className='help-message '+who;const bubble=document.createElement('div');bubble.className='help-bubble';bubble.textContent=txt;wrap.append(bubble);msg.append(wrap);scroll();return wrap;}
function dots(){const wrap=document.createElement('div');wrap.className='help-message bot';wrap.id='helpTyping';wrap.innerHTML='<div class="help-bubble help-typing"><i></i><i></i><i></i></div>';msg.append(wrap);scroll();}
function showLinks(wrap,k){const l=topics[k]?.l||[];if(!l.length)return;const row=document.createElement('div');row.className='help-link-row';l.forEach(([url,label])=>{const a=document.createElement('a');a.className='help-quick-link';if(url==='SUPPORT'){a.href=SUPPORT;a.target='_blank';a.rel='noopener noreferrer';a.innerHTML='<i class="fa-brands fa-telegram"></i>'+esc(lang==='en'?'Official Telegram support':'Bantuan Telegram Resmi');}else{a.href=url;a.innerHTML='<i class="fa-solid fa-arrow-up-right-from-square"></i>'+esc(lang==='en'?(linkEN[label]||label):label);}row.append(a);});wrap.append(row);}
function feedback(wrap){const row=document.createElement('div');row.className='help-feedback';const yes=document.createElement('button'),no=document.createElement('button');yes.innerHTML='<i class="fa-solid fa-thumbs-up"></i> '+translations[lang].yes;no.innerHTML='<i class="fa-solid fa-circle-question"></i> '+translations[lang].no;yes.onclick=()=>{yes.disabled=true;no.disabled=true;yes.classList.add('is-selected');addMessage(translations[lang].thanks);renderTopics();};no.onclick=()=>{yes.disabled=true;no.disabled=true;addMessage(translations[lang].sorry);renderTopics();};row.append(yes,no);wrap.append(row);}
function reply(txt,done){if(typing)return;typing=true;dots();setTimeout(()=>{$('helpTyping')?.remove();const wrap=addMessage('');const b=wrap.querySelector('.help-bubble');let i=0;function tick(){if(!b.isConnected){typing=false;return;}i=Math.min(txt.length,i+4);b.textContent=txt.slice(0,i);scroll();if(i<txt.length)setTimeout(tick,13);else{typing=false;if(done)done(wrap);}}tick();},450);}
function topic(k){if(!topics[k]||typing)return;acts.innerHTML='';addMessage(title(k),'user');reply(text(k),wrap=>{showLinks(wrap,k);feedback(wrap);});}
function renderTopics(search=''){acts.innerHTML='';const q=search.trim().toLowerCase();let count=0;groups.forEach(g=>{const matched=g.keys.filter(k=>topics[k]&&(!q||title(k).toLowerCase().includes(q)||text(k).toLowerCase().includes(q)||k.toLowerCase().includes(q)));if(!matched.length)return;const head=document.createElement('div');head.className='help-topic-category';head.textContent=lang==='en'?g.en:g.id;acts.append(head);matched.forEach(k=>{count++;const b=document.createElement('button');b.className='help-topic';b.innerHTML='<i class="fa-solid fa-circle-question"></i><span>'+esc(title(k))+'</span>';b.onclick=()=>topic(k);acts.append(b);});});if(!count){const empty=document.createElement('div');empty.className='help-empty';empty.textContent=translations[lang].empty;acts.append(empty);}const reset=document.createElement('button');reset.className='help-topic';reset.innerHTML='<i class="fa-solid fa-rotate-left"></i><span>'+translations[lang].restart+'</span>';reset.onclick=restart;acts.append(reset);scroll();}
function start(){if(started)return;started=true;inputArea.hidden=false;addMessage(translations[lang].start,'user');reply(translations[lang].startPrompt,()=>renderTopics());input.focus();}
function restart(){msg.innerHTML='';addMessage(translations[lang].welcome);acts.innerHTML='';const b=document.createElement('button');b.className='help-start';b.innerHTML='<i class="fa-solid fa-play"></i> '+translations[lang].start;b.onclick=start;acts.append(b);inputArea.hidden=true;started=false;}
function match(q){q=q.toLowerCase();const rules=[['forgot',/lupa.*(password|kata sandi)|forgot.*password|reset.*password/],['login',/login|masuk|sign.?in/],['register',/daftar|register|sign.?up|buat akun/],['openTelegram',/buka.*(link|media).*(telegram|bot)|telegram.*(link|bot)|join.*channel|join.*grup|centang hijau|start bot/],['buyMedia',/beli.*media|buy.*media|checkout.*media/],['freeCheap',/murah|diskon|promo|hemat/],['buyGroups',/beli.*(group|grup).*(vip)|buy.*vip.*group/],['joinGroups',/gabung.*(group|grup)|join.*group|invite.*vip/],['buyVip',/beli.*vip|upgrade.*vip|membership/],['nokos',/nokos|kode otp|otp code|nomor virtual|ready no/],['withdrawIssue',/withdraw.*(gagal|pending|ditolak)|pencairan.*(lama|gagal)/],['withdraw',/withdraw|cairkan|pencairan|tarik saldo/],['wallet',/saldo|balance|komisi|commission/],['publisher',/publisher|ajukan.*publisher/],['commission',/afiliasi|affiliate|referral|link promosi/],['earn',/cuan|penghasilan|earn.*money|earn.*income/],['endorse',/endorse|campaign/],['pastelink',/pastelink|paste link|buat.*paste/],['pasteTrouble',/pastelink.*(error|gagal|rusak)|link paste.*error/],['autolinkError',/autolink.*(error|gagal|salah|redirect)|redirect.*salah/],['autolink',/autolink|auto link/],['posts',/posts|postingan|feed/],['postCreate',/buat.*post|buat.*posting|publish post/],['paidNotReceived',/sudah bayar|paid.*(not|but)|media.*belum.*(dikirim|masuk)/],['paymentPending',/pending.*bayar|bayar.*pending|payment pending/],['paymentFailed',/bayar.*gagal|payment.*fail|payment.*error/],['linkError',/link.*(rusak|expired|kedaluwarsa|error)|media.*(error|rusak)/],['browser',/website.*(lambat|error)|tombol.*(error|tidak.*fungsi)/],['history',/histori|history|riwayat.*(tonton|beli)/],['profile',/profil|profile|foto profil/],['search',/cari|search|pencarian/],['safeLinks',/aman|safety|phishing|link.*mencurigakan/],['contact',/admin|support|hubungi/]];for(const [k,re] of rules)if(re.test(q)&&topics[k])return k;return null;}
function submit(q){q=q.trim();if(!q||typing)return;addMessage(q,'user');input.value='';const k=match(q);if(k)reply(lang==='en'?'I found a guide that may help: '+title(k):'Panduan yang mungkin cocok: '+title(k),()=>topic(k));else reply(translations[lang].notfound,()=>renderTopics(q));}
$('helpStart').addEventListener('click',start);$('helpLang').addEventListener('click',()=>{lang=lang==='id'?'en':'id';localStorage.setItem('boxcellink_lang',lang);localize();if(started)renderTopics();});document.addEventListener('boxcellink:language-change',e=>{lang=(e.detail?.lang||lang)==='en'?'en':'id';localize();if(started)renderTopics();});$('helpQuestionForm').addEventListener('submit',e=>{e.preventDefault();submit(input.value);});localize();
})();
